import { spawn } from "node:child_process";

const bin = process.env.HOME + "/.bun/bin/gbrain";
const child = spawn(bin, ["serve", "--surface", "starter", "--advertise", "verbs"], {
  env: { ...process.env, GBRAIN_HOME: process.env.HOME },
  stdio: ["pipe", "pipe", "pipe"],
});

let buf = "";
const pending = new Map();
child.stdout.on("data", (d) => {
  buf += d.toString();
  let i;
  while ((i = buf.indexOf("\n")) >= 0) {
    const line = buf.slice(0, i).trim();
    buf = buf.slice(i + 1);
    if (!line) continue;
    let msg;
    try { msg = JSON.parse(line); } catch { continue; }
    if (msg.id !== undefined && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
    }
  }
});
let stderrText = "";
child.stderr.on("data", (d) => (stderrText += d.toString()));

let nextId = 1;
function rpc(method, params) {
  const id = nextId++;
  const p = new Promise((res, rej) => {
    pending.set(id, res);
    setTimeout(() => rej(new Error("timeout " + method)), 60000);
  });
  child.stdin.write(JSON.stringify({ jsonrpc: "2.0", id, method, params }) + "\n");
  return p;
}
function notify(method, params) {
  child.stdin.write(JSON.stringify({ jsonrpc: "2.0", method, params }) + "\n");
}

try {
  const init = await rpc("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "openclaw-verify", version: "0.0.1" },
  });
  console.log("SERVER:", JSON.stringify(init.result?.serverInfo ?? init));
  notify("notifications/initialized", {});

  const tools = await rpc("tools/list", {});
  const names = (tools.result?.tools ?? []).map((t) => t.name);
  console.log("TOOLS:", names.join(", "));

  const marker = "OpenClaw install round trip " + new Date().toISOString();
  const rem = await rpc("tools/call", {
    name: "remember",
    arguments: {
      fact: marker,
      entity_slug: "install-check",
      content_origin: "inferred",
      provenance: "install-check",
    },
  });
  console.log("REMEMBER:", JSON.stringify(rem.result ?? rem.error).slice(0, 800));

  const rec = await rpc("tools/call", {
    name: "recall",
    arguments: { query: "OpenClaw install round trip" },
  });
  const text = JSON.stringify(rec.result ?? rec.error);
  console.log("RECALL:", text.slice(0, 1200));
  console.log("ROUND_TRIP_MATCH:", text.includes(marker));
} catch (e) {
  console.error("PROBE_ERROR:", e.message);
  process.exitCode = 1;
} finally {
  child.kill();
  if (stderrText.trim()) console.error("STDERR:", stderrText.slice(0, 1500));
}

